showHistory = () => {
    const { selectedTime } = this.state;
    if (!selectedTime) {
        alert('Please select a time period.');
        return;
    }

    const pastTime = this.calculateTime(selectedTime);
    console.log(`Fetching location history from: ${pastTime}`);

    this.setState({ currentTimestamp: pastTime }, () => {
        fetch(`http://localhost:3001/locationhistory?pet_id=1&time=${pastTime}`)
            .then((response) => {
                if (!response.ok) {
                    return response.text().then(text => { throw new Error(text) });
                }
                return response.json();
            })
            .then((data) => {
                console.log(`Fetched location history: ${JSON.stringify(data)}`);
                this.setState({ petLocations: data, currentPointIndex: 0, currentPhoto: null, showtrack: true }, this.playHistory);
                this.initPanorama();
            })
            .catch((error) => console.error('Error fetching location history:', error));
    });
};
